"""
V6 Complete Analysis: importance vs random phase gradient comparison.
Loads v6 importance (with per_problem_ii) and v5 random results.
Computes per-problem bootstrap CI for median phase gradient.
"""

import json
import numpy as np
import argparse
import sys
from pathlib import Path
from scipy import stats as sp_stats

BASE = Path("/root/autodl-tmp/pacs")
SPARSITY_MAP = {
    "s015": "0.15",
    "s020": "0.2",
    "s025": "0.25",
    "s030": "0.3",
}
SPARSITY_LABELS = ["s015", "s020", "s025", "s030"]
PHASES = ["high", "mid", "low"]
PHASE_KEYS = {"high": "high_sparsity", "mid": "mid_sparsity", "low": "low_sparsity"}


def load_results(path):
    with open(path) as f:
        return json.load(f)


def get_per_problem_ii(data, sparsity_key):
    """Extract per-problem II values (nulls filtered). Returns {phase: np.array}."""
    if "per_problem_ii" not in data:
        return None
    ppi_list = data["per_problem_ii"].get(sparsity_key, [])
    result = {}
    for phase in PHASES:
        vals = [p[f"ii_{phase}"] for p in ppi_list if p[f"ii_{phase}"] is not None]
        result[phase] = np.array(vals) if vals else np.array([])
    return result


def get_paired_ii(data, sparsity_key, phase_a, phase_b):
    """Get paired values where both phases are non-null for same problem."""
    if "per_problem_ii" not in data:
        return np.array([]), np.array([])
    ppi_list = data["per_problem_ii"].get(sparsity_key, [])
    a_vals, b_vals = [], []
    for p in ppi_list:
        va, vb = p[f"ii_{phase_a}"], p[f"ii_{phase_b}"]
        if va is not None and vb is not None:
            a_vals.append(va)
            b_vals.append(vb)
    return np.array(a_vals), np.array(b_vals)


def bootstrap_gradient_paired(ii_high, ii_low, n_bootstrap=1000, ci=0.95, seed=42):
    """
    Paired problem-level bootstrap for gradient = median(II_low) / median(II_high).
    Resampling unit: problem (NOT segment).
    """
    n = len(ii_high)
    if n == 0:
        return None

    point_est = float(np.median(ii_low) / np.median(ii_high))

    rng = np.random.RandomState(seed)
    gradients = []
    for _ in range(n_bootstrap):
        idx = rng.choice(n, size=n, replace=True)
        med_h = np.median(ii_high[idx])
        if med_h > 0:
            gradients.append(np.median(ii_low[idx]) / med_h)

    if not gradients:
        return None

    gradients = np.array(gradients)
    alpha = 1 - ci
    return {
        "gradient": point_est,
        "ci_low": float(np.percentile(gradients, 100 * alpha / 2)),
        "ci_high": float(np.percentile(gradients, 100 * (1 - alpha / 2))),
        "p_le_1": float(np.mean(gradients <= 1.0)),
        "n_paired": n,
        "n_bootstrap": n_bootstrap,
    }


def bootstrap_gradient_unpaired(ii_high, ii_low, n_bootstrap=1000, ci=0.95, seed=42):
    """Independent resampling of high/low (not necessarily same problems)."""
    if len(ii_high) == 0 or len(ii_low) == 0:
        return None

    point_est = float(np.median(ii_low) / np.median(ii_high))

    rng = np.random.RandomState(seed)
    gradients = []
    for _ in range(n_bootstrap):
        h = np.median(ii_high[rng.choice(len(ii_high), len(ii_high), replace=True)])
        if h > 0:
            l = np.median(ii_low[rng.choice(len(ii_low), len(ii_low), replace=True)])
            gradients.append(l / h)

    if not gradients:
        return None

    gradients = np.array(gradients)
    alpha = 1 - ci
    return {
        "gradient": point_est,
        "ci_low": float(np.percentile(gradients, 100 * alpha / 2)),
        "ci_high": float(np.percentile(gradients, 100 * (1 - alpha / 2))),
        "p_le_1": float(np.mean(gradients <= 1.0)),
        "n_high": len(ii_high),
        "n_low": len(ii_low),
        "n_bootstrap": n_bootstrap,
    }


def get_agg_median(data, phase_key, sparsity_key):
    return data.get("interaction_index", {}).get(phase_key, {}).get(sparsity_key, {}).get("median", float("nan"))


def get_agg_stats(data, phase_key, sparsity_key):
    return data.get("interaction_index", {}).get(phase_key, {}).get(sparsity_key, {})


def fmt(v, w=10, d=4):
    if v is None or (isinstance(v, float) and np.isnan(v)):
        return f"{'N/A':>{w}}"
    return f"{v:>{w}.{d}f}"


def main():
    parser = argparse.ArgumentParser(description="V6 analysis: importance vs random")
    parser.add_argument("--n-bootstrap", type=int, default=1000)
    parser.add_argument("--sparsity", nargs="*", default=None,
                        help="Subset e.g. s025 s030")
    args = parser.parse_args()

    labels = args.sparsity if args.sparsity else SPARSITY_LABELS

    # ── Load data ──
    v6, v5 = {}, {}
    for sl in labels:
        for tag, store, tpl in [
            ("v6_imp", v6, "profiling_output_v6_importance_{}/profiling_results.json"),
            ("v5_rnd", v5, "profiling_output_v5_random_{}/profiling_results.json"),
        ]:
            p = BASE / tpl.format(sl)
            if p.exists():
                store[sl] = load_results(p)
                print(f"  loaded {tag} {sl}")
            else:
                print(f"  MISSING {tag} {sl}")
    print()

    # ── Table 1: Per-Problem Bootstrap Phase Gradient (importance) ──
    sep = "=" * 82
    print(sep)
    print("Table 1: Per-Problem Bootstrap Phase Gradient (importance)")
    print("  gradient = median(II_low) / median(II_high)")
    print(sep)

    hdr = f"{'Sparsity':>10} | {'Gradient':>10} | {'95% CI':>22} | {'p(g≤1)':>8} | {'n_paired':>8}"
    print(hdr)
    print("-" * len(hdr))

    gradient_results = {}
    for sl in labels:
        if sl not in v6:
            continue
        sk = SPARSITY_MAP[sl]
        hi, lo = get_paired_ii(v6[sl], sk, "high", "low")
        res = bootstrap_gradient_paired(hi, lo, n_bootstrap=args.n_bootstrap)
        if res:
            gradient_results[sl] = res
            ci = f"[{res['ci_low']:.2f}, {res['ci_high']:.2f}]"
            print(f"{sl:>10} | {res['gradient']:>10.2f} | {ci:>22} | {res['p_le_1']:>8.4f} | {res['n_paired']:>8}")
        else:
            print(f"{sl:>10} | {'N/A':>10} | {'N/A':>22} | {'N/A':>8} | {'N/A':>8}")

    # Unpaired variant
    print()
    print("  Unpaired variant (independent resampling of high/low):")
    hdr2 = f"{'Sparsity':>10} | {'Gradient':>10} | {'95% CI':>22} | {'p(g≤1)':>8} | {'n_high':>6} | {'n_low':>6}"
    print(hdr2)
    print("-" * len(hdr2))

    for sl in labels:
        if sl not in v6:
            continue
        sk = SPARSITY_MAP[sl]
        ppi = get_per_problem_ii(v6[sl], sk)
        if ppi is None:
            continue
        res = bootstrap_gradient_unpaired(ppi["high"], ppi["low"], n_bootstrap=args.n_bootstrap)
        if res:
            ci = f"[{res['ci_low']:.2f}, {res['ci_high']:.2f}]"
            print(f"{sl:>10} | {res['gradient']:>10.2f} | {ci:>22} | {res['p_le_1']:>8.4f} | {res['n_high']:>6} | {res['n_low']:>6}")

    print()

    # ── Table 2: Importance vs Random Comparison ──
    print(sep)
    print("Table 2: Importance vs Random Comparison (aggregated medians)")
    print("  Lower II = less component interaction = pruning more independent.")
    print("  * v5 random lacks per_problem_ii → Cohen's d / MW unavailable.")
    print(sep)

    hdr3 = f"{'Sparsity':>10} | {'Phase':>5} | {'Imp med':>10} | {'Rnd med':>10} | {'Ratio':>8} | {'Winner':>8}"
    print(hdr3)
    print("-" * len(hdr3))

    comparison = {}
    for sl in labels:
        if sl not in v6:
            continue
        sk = SPARSITY_MAP[sl]
        comparison[sl] = {}

        for phase in PHASES:
            pk = PHASE_KEYS[phase]

            # Use per-problem median for importance if available
            ppi = get_per_problem_ii(v6[sl], sk)
            if ppi and len(ppi[phase]) > 0:
                imp_med = float(np.median(ppi[phase]))
            else:
                imp_med = get_agg_median(v6[sl], pk, sk)

            rnd_med = get_agg_median(v5[sl], pk, sk) if sl in v5 else float("nan")

            if not np.isnan(imp_med) and not np.isnan(rnd_med) and rnd_med != 0:
                ratio = imp_med / rnd_med
            else:
                ratio = float("nan")

            winner = "imp" if imp_med < rnd_med else ("rnd" if rnd_med < imp_med else "tie")
            if np.isnan(imp_med) or np.isnan(rnd_med):
                winner = "?"

            comparison[sl][phase] = {
                "imp_median": imp_med,
                "rnd_median": rnd_med,
                "ratio": ratio,
                "winner": winner,
            }

            print(f"{sl:>10} | {phase:>5} | {fmt(imp_med)} | {fmt(rnd_med)} | {fmt(ratio, 8, 3)} | {winner:>8}")

        print("-" * len(hdr3))

    print()

    # ── Table 3: Strategy-Dependent Reversal Check ──
    print(sep)
    print("Table 3: Strategy-Dependent Reversal Check")
    print("  Crossover = importance wins one phase but random wins another")
    print(sep)

    hdr4 = f"{'Sparsity':>10} | {'High winner':>12} | {'Mid winner':>12} | {'Low winner':>12} | {'Crossover':>10}"
    print(hdr4)
    print("-" * len(hdr4))

    reversal = {}
    for sl in labels:
        if sl not in comparison:
            continue
        c = comparison[sl]
        winners = {p: c[p]["winner"] for p in PHASES}
        real_winners = [w for w in winners.values() if w not in ("?", "tie")]
        crossover = len(set(real_winners)) > 1

        reversal[sl] = {**winners, "crossover": crossover}

        xo = "YES" if crossover else "NO"
        print(f"{sl:>10} | {winners['high']:>12} | {winners['mid']:>12} | {winners['low']:>12} | {xo:>10}")

    print()

    # ── Per-problem II distribution stats (importance only) ──
    print(sep)
    print("Supplementary: Per-problem II distribution (importance, non-null)")
    print(sep)

    hdr5 = f"{'Sparsity':>10} | {'Phase':>5} | {'n':>4} | {'median':>10} | {'mean':>10} | {'std':>10} | {'min':>10} | {'max':>10}"
    print(hdr5)
    print("-" * len(hdr5))

    for sl in labels:
        if sl not in v6:
            continue
        sk = SPARSITY_MAP[sl]
        ppi = get_per_problem_ii(v6[sl], sk)
        if ppi is None:
            continue
        for phase in PHASES:
            arr = ppi[phase]
            if len(arr) == 0:
                print(f"{sl:>10} | {phase:>5} | {'0':>4} | {'N/A':>10} | {'N/A':>10} | {'N/A':>10} | {'N/A':>10} | {'N/A':>10}")
                continue
            print(f"{sl:>10} | {phase:>5} | {len(arr):>4} | {np.median(arr):>10.4f} | {np.mean(arr):>10.4f} | {np.std(arr):>10.4f} | {np.min(arr):>10.4f} | {np.max(arr):>10.4f}")
        print("-" * len(hdr5))

    print()

    # ── Save JSON ──
    summary = {
        "gradient_bootstrap_paired": {
            k: {kk: (vv if not isinstance(vv, float) or not np.isnan(vv) else None)
                for kk, vv in v.items()}
            for k, v in gradient_results.items()
        },
        "comparison": {
            sl: {
                ph: {k: (v if not isinstance(v, float) or not np.isnan(v) else None)
                     for k, v in vals.items()}
                for ph, vals in phases.items()
            }
            for sl, phases in comparison.items()
        },
        "reversal_check": reversal,
        "metadata": {
            "v6_loaded": list(v6.keys()),
            "v5_loaded": list(v5.keys()),
            "n_bootstrap": args.n_bootstrap,
            "note": "Cohen's d / MW p-value not computed: v5 random lacks per_problem_ii",
        },
    }

    out_path = BASE / "analysis" / "v6_analysis_results.json"
    with open(out_path, "w") as f:
        json.dump(summary, f, indent=2, default=str)
    print(f"Summary saved to {out_path}")


if __name__ == "__main__":
    main()
PYEOF
